const fs = require('fs');

function isPlainObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function mergeDefaults(defaults, userConfig) {
  const result = { ...defaults };
  for (const key of Object.keys(userConfig)) {
    const userValue = userConfig[key];
    if (isPlainObject(userValue) && isPlainObject(result[key])) {
      result[key] = mergeDefaults(result[key], userValue);
    } else {
      result[key] = userValue;
    }
  }
  return result;
}

function loadConfig(filePath, defaults = {}) {
  let userConfig = {};
  try {
    userConfig = JSON.parse(fs.readFileSync(filePath, 'utf8'));
  } catch (err) {
    if (err.code !== 'ENOENT') throw err;
  }
  return mergeDefaults(defaults, userConfig);
}

module.exports = { loadConfig };
